#!/usr/bin/env node
/**
 * Pre-configure Chrome extension storage for E2E testing
 */

import { readFileSync, writeFileSync, mkdirSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const rootDir = join(__dirname, '..');
const userDataDir = join(rootDir, 'test-user-data');
const storageDir = join(userDataDir, 'Default', 'Local Extension Settings');

// Extension ID will be generated by Chrome, so we'll use a known one
// Actually, we'll have to get it from the running browser first
// For now, create a leveldb with test data

const testFaceImage = readFileSync(join(rootDir, 'public/sample-images/model-2.jpg'));
const testFaceDataUrl = `data:image/jpeg;base64,${testFaceImage.toString('base64')}`;

const enrollmentData = {
  enrollmentData: {
    frontalFrame: testFaceDataUrl,
    enrolledAt: Date.now()
  },
  enabled: true,
  provider: 'local'
};

console.log('Test data prepared, will be set via browser context');
console.log(`Data size: ${JSON.stringify(enrollmentData).length} bytes`);

// Export for use by e2e script
export { enrollmentData };
